# Initially generated by GitHub Copilot.
import io
import os
import tempfile
import unittest

from tmpl_survey import survey_dot


class TestTmplSurveyFocusedTargets(unittest.TestCase):
    def test_focused_targets_include_trial_templates(self):
        got = [(x.tmpl_name, x.slug, x.collapse) for x in survey_dot._FOCUSED_TARGETS]
        expected = [
            ("מ:כפול", "kpvl", False),
            ("נוסח", "nvox", True),
            ("מ:פסוק", "povq", False),
            ("כו״ק", "kvq", False),
            ("מ:דחי", "dxy", False),
        ]
        self.assertEqual(expected, got)

    def test_write_focused_dot_files_writes_all_expected_dots(self):
        stack_counts = {
            ("מ:כפול", "C"): 1,
            ("נוסח", "C"): 1,
            ("מ:פסוק", "D"): 1,
            ("כו״ק", "E"): 1,
            ("מ:דחי", "E"): 1,
        }
        slugs = [x.slug for x in survey_dot._FOCUSED_TARGETS]

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            svg_stem = os.path.join(tdir, "svg", "plain")
            os.makedirs(os.path.dirname(svg_stem), exist_ok=True)

            render_calls = []
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = (
                lambda dot_path, svg_path, generator_file=None: render_calls.append(
                    (dot_path, svg_path, generator_file)
                )
            )
            try:
                survey_dot.write_focused_dot_files(
                    stack_counts, stem, svg_stem=svg_stem
                )
            finally:
                survey_dot.render_svg = orig_render_svg

            for slug in slugs:
                dot_path = f"{stem}-{slug}-call-graph.dot"
                self.assertTrue(os.path.exists(dot_path), dot_path)

            self.assertEqual(len(slugs), len(render_calls))

    def test_focused_edge_extraction_matches_nusach_suffixes(self):
        stack_counts = {
            ("מ:דחי", "C/נוסח@1"): 3,
            ("מ:עלייה", "C/נוסח@2/מ:דחי"): 5,
        }

        edges = survey_dot._focused_edges_from_stack_counts(stack_counts, target="נוסח")

        self.assertEqual(3, edges[("C", "נוסח@1")])
        self.assertEqual(5, edges[("C", "נוסח@2")])
        self.assertEqual(3, edges[("נוסח@1", "מ:דחי")])
        self.assertEqual(5, edges[("נוסח@2", "מ:דחי")])

    def test_focused_dxy_graph_excludes_cross_stack_transitive_leakage(self):
        stack_counts = {
            ("נוסח", "C"): 2,
            ("נוסח", "D"): 3,
            ("נוסח", "E"): 5,
            ("מ:דחי", "E/נוסח"): 7,
            ("מ:אות-ג", "E/נוסח/מ:דחי"): 11,
            ("מ:אות-ס", "E/נוסח/מ:דחי/מ:אות-ג"): 13,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            dxy_dot_path = f"{stem}-dxy-call-graph.dot"
            with open(dxy_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"E" -> "מ:דחי" [label="31"]', dot_text)
        self.assertIn('"מ:דחי" -> "מ:אות-ג" [label="24"]', dot_text)
        self.assertIn('"מ:אות-ג" -> "מ:אות-ס" [label="13"]', dot_text)
        self.assertNotIn('"C" -> "נוסח"', dot_text)
        self.assertNotIn('"D" -> "נוסח"', dot_text)
        self.assertNotIn('"נוסח"', dot_text)
        self.assertIn("מ:כפול, נוסח have been discarded", dot_text)

    def test_focused_nusach_uses_targeted_discard_set(self):
        stack_counts = {
            ("נוסח@1", "C"): 2,
            ("נוסח@2", "C"): 4,
            ("מ:דחי", "C/נוסח@1"): 3,
            ("מ:עלייה", "C/נוסח@2"): 7,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            nusach_dot_path = f"{stem}-nvox-call-graph.dot"
            with open(nusach_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"C" -> "נוסח@1" [label="2"]', dot_text)
        self.assertIn('"C" -> "נוסח@2" [label="11"]', dot_text)
        self.assertIn('"נוסח@2" -> "מ:עלייה" [label="7"]', dot_text)
        self.assertNotIn('"נוסח@1" -> "מ:דחי" [label="3"]', dot_text)
        self.assertIn("כו״ק", dot_text)
        self.assertIn("מ:קו״כ-אם-2", dot_text)
        self.assertIn("מ:כו״ק מיוחד", dot_text)
        self.assertIn("מ:קמץ", dot_text)
        self.assertIn("מ:דחי", dot_text)
        self.assertIn("have been discarded", dot_text)

    def test_focused_pasuk_skips_standard_discard_set(self):
        stack_counts = {
            ("נוסח", "D"): 2,
            ("מ:פסוק", "D/נוסח"): 3,
            ("מ:עלייה", "D/נוסח/מ:פסוק"): 5,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            pasuk_dot_path = f"{stem}-povq-call-graph.dot"
            with open(pasuk_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"D" -> "נוסח" [label="8"]', dot_text)
        self.assertIn('"נוסח" -> "מ:פסוק" [label="8"]', dot_text)
        self.assertIn('"מ:פסוק" -> "מ:עלייה" [label="5"]', dot_text)
        self.assertNotIn("have been discarded", dot_text)

    def test_focused_nusach_special_label_only_for_dead_end_direct_children(self):
        stack_counts = {
            ("נוסח", "C"): 1,
            ("A1", "C/נוסח"): 3,
            ("A2", "C/נוסח"): 5,
            ("X", "C/נוסח"): 2,
            ("B1", "C/נוסח/X"): 7,
            ("B2", "C/נוסח/X"): 11,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            nusach_dot_path = f"{stem}-nvox-call-graph.dot"
            with open(nusach_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"dead-end children of נוסח" [tooltip="A1\nA2"]', dot_text)
        self.assertIn('"נוסח" -> "dead-end children of נוסח" [label="8"]', dot_text)
        self.assertIn('"X" -> "B1, ..." [label="18"]', dot_text)
        self.assertNotIn('"X" -> "dead-end children of נוסח"', dot_text)
        self.assertNotIn("direct children of נוסח", dot_text)

    def test_focused_target_node_has_highlight_style(self):
        stack_counts = {
            ("מ:דחי", "E"): 7,
            ("מ:אות-ג", "E/מ:דחי"): 11,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            dxy_dot_path = f"{stem}-dxy-call-graph.dot"
            with open(dxy_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn(
            '"מ:דחי" [fillcolor="lightgoldenrod1", style="filled", penwidth=2.5];',
            dot_text,
        )
        self.assertNotIn('"E" [fillcolor="lightgoldenrod1"', dot_text)
        self.assertNotIn('"מ:אות-ג" [fillcolor="lightgoldenrod1"', dot_text)

    def test_focus_style_uses_group_membership_not_rep_name(self):
        edges = {
            ("C", "A"): 5,
        }
        groups = {
            "A": ["A", "נוסח"],
        }

        fp = io.StringIO()
        survey_dot._write_dot(
            edges,
            groups,
            fp,
            note=None,
            focus_target="נוסח",
        )
        dot_text = fp.getvalue()

        self.assertIn(
            '"A, ..." [tooltip="A\nנוסח", fillcolor="lightgoldenrod1", '
            'style="filled", penwidth=2.5];',
            dot_text,
        )


if __name__ == "__main__":
    unittest.main()
